const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def merge(self, intervals: List[List[int]]) -> List[List[int]]:", "        intervals.sort()", "        ans = []", "        (st, ed) = intervals[0]", "        for (s, e) in intervals[1:]:", "            if ed < s:", "                ans.append([st, ed])", "                (st, ed) = (s, e)", "            else:", "                ed = max(ed, e)", "        ans.append([st, ed])", "        return ans"], "Java": ["import java.util.*;", "class Solution {", "    public int[][] merge(int[][] intervals) {", "        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));", "        int st = intervals[0][0], ed = intervals[0][1];", "        List<int[]> ans = new ArrayList<>();", "        for (int i = 1; i < intervals.length; ++i) {", "            int s = intervals[i][0], e = intervals[i][1];", "            if (ed < s) {", "                ans.add(new int[] {st, ed});", "                st = s;", "                ed = e;", "            } else {", "                ed = Math.max(ed, e);", "            }", "        }", "        ans.add(new int[] {st, ed});", "        return ans.toArray(new int[ans.size()][]);", "    }", "}"]};
